{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"pygments_lexer":"ipython3","nbconvert_exporter":"python","version":"3.6.4","file_extension":".py","codemirror_mode":{"name":"ipython","version":3},"name":"python","mimetype":"text/x-python"},"kaggle":{"accelerator":"none","dataSources":[],"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"from transformers import pipeline\nimport torch\n\n# Check if GPU is available\ndevice = 0 if torch.cuda.is_available() else -1  # -1 for CPU, 0 for GPU\n\n# Load the summarization pipeline\nmodel_name = \"facebook/bart-large-cnn\"\nsummarizer = pipeline(\"summarization\", model=model_name, device=device)\n\ndef summarize_text(text, summary_ratio=0.3):\n    try:\n        summary = summarizer(text, max_length=int(len(text.split()) * summary_ratio), min_length=50, do_sample=False)\n        return summary[0]['summary_text']\n    except Exception as e:\n        return f\"Error: {str(e)}\"\n","metadata":{"_uuid":"8f2839f25d086af736a60e9eeb907d3b93b6e0e5","_cell_guid":"b1076dfc-b9ad-4769-8c92-a6c4dae69d19","trusted":true},"outputs":[],"execution_count":null}]}